#!/usr/bin/env bash
# runs set-release-version.sh against temporary copies of the CLI's and the app's
# Cargo.toml and Cargo.lock, and the committed files, checking the exit status,
# the cause the script names, and what the files hold afterwards.
set -euo pipefail

scripts="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
set_version="${scripts}/set-release-version.sh"
committed="$(cd "${scripts}/../.." && pwd)"
work="$(mktemp -d)"
trap 'rm -rf -- "$work"' EXIT

# the dependencies and the registry entries hold the placeholder too, so a case
# fails if the script replaces anything but the versions it owns.
cli_manifest='[workspace]
members = ["."]

[package]
name = "marshal-cli"
version = "0.0.0-dev"
edition = "2024"

[dependencies]
example = { version = "0.0.0-dev" }

[dependencies.other]
version = "0.0.0-dev"
'
cli_lockfile='# This file is automatically @generated by Cargo.
version = 4

[[package]]
name = "example"
version = "0.0.0-dev"
source = "registry+https://github.com/rust-lang/crates.io-index"

[[package]]
name = "marshal-cli"
version = "0.0.0-dev"
dependencies = [
 "example",
]
'
app_manifest='[workspace]
resolver = "3"
members = ["crates/app", "crates/modes"]

[workspace.package]
version = "0.0.0-dev"
edition = "2024"

[workspace.dependencies]
example = { version = "0.0.0-dev" }
'
app_lockfile='# This file is automatically @generated by Cargo.
version = 4

[[package]]
name = "example"
version = "0.0.0-dev"
source = "registry+https://github.com/rust-lang/crates.io-index"

[[package]]
name = "marshal-app"
version = "0.0.0-dev"
dependencies = [
 "marshal-cli",
 "marshal-modes",
]

[[package]]
name = "marshal-cli"
version = "0.0.0-dev"

[[package]]
name = "marshal-lookalike"
version = "0.0.0-dev"
source = "registry+https://github.com/rust-lang/crates.io-index"

[[package]]
name = "marshal-modes"
version = "0.0.0-dev"
'

failures=0
fail() {
  echo "FAIL $*" >&2
  failures=$((failures + 1))
}

# fixture <directory> [<cli manifest> [<cli lockfile> [<app manifest> [<app lockfile>]]]]
fixture() {
  mkdir -p "$1/cli" "$1/app"
  printf '%s' "${2:-$cli_manifest}" >"${1}/cli/Cargo.toml"
  printf '%s' "${3:-$cli_lockfile}" >"${1}/cli/Cargo.lock"
  printf '%s' "${4:-$app_manifest}" >"${1}/app/Cargo.toml"
  printf '%s' "${5:-$app_lockfile}" >"${1}/app/Cargo.lock"
}

# expect <case> <exit status> <text the output must contain> <version> <directory>
expect() {
  local name="$1" want_status="$2" want_text="$3" output status=0
  shift 3
  output="$(bash "$set_version" "$@" 2>&1)" || status=$?
  if [[ $status -ne $want_status ]]; then
    fail "${name}: exit ${status}, expected ${want_status}: ${output}"
    return 1
  elif [[ "$output" != *"$want_text"* ]]; then
    fail "${name}: the output does not contain '${want_text}': ${output}"
    return 1
  fi
}

# holds <case> <file> <expected content>, ignoring trailing newlines on both sides.
holds() {
  if [[ "$(cat "$2")" != "$(printf '%s' "$3")" ]]; then
    fail "${1}: ${2#"$work"/} holds:
$(cat "$2")"
    return 1
  fi
}

# unchanged <case> <directory>: all four files hold the fixtures.
unchanged() {
  holds "$1" "$2/cli/Cargo.toml" "$cli_manifest" \
    && holds "$1" "$2/cli/Cargo.lock" "$cli_lockfile" \
    && holds "$1" "$2/app/Cargo.toml" "$app_manifest" \
    && holds "$1" "$2/app/Cargo.lock" "$app_lockfile"
}

# stamped <text> <version> <line numbers>: the text with those lines' version replaced.
stamped() {
  printf '%s' "$1" | awk -v version="$2" -v lines=" $3 " '
    index(lines, " " NR " ") { sub(/"[^"]*"/, "\"" version "\"") }
    { print }
  '
}

# the lines each fixture's owned versions are on.
cli_manifest_lines=6
cli_lockfile_lines=11
app_manifest_lines=6
app_lockfile_lines="11 19 28"

# stamped_all <case> <directory> <version>
stamped_all() {
  holds "$1" "$2/cli/Cargo.toml" "$(stamped "$cli_manifest" "$3" "$cli_manifest_lines")" \
    && holds "$1" "$2/cli/Cargo.lock" "$(stamped "$cli_lockfile" "$3" "$cli_lockfile_lines")" \
    && holds "$1" "$2/app/Cargo.toml" "$(stamped "$app_manifest" "$3" "$app_manifest_lines")" \
    && holds "$1" "$2/app/Cargo.lock" "$(stamped "$app_lockfile" "$3" "$app_lockfile_lines")"
}

case_dir="${work}/release"
fixture "$case_dir"
if expect "a release version" 0 "Set the CLI's and the app's version to 1.2.3" 1.2.3 "$case_dir" \
  && stamped_all "a release version" "$case_dir" 1.2.3; then
  echo "ok   a release version reaches the CLI's and the app's files, and only the versions they own"
fi

case_dir="${work}/prerelease"
fixture "$case_dir"
if expect "a prerelease version" 0 "to 0.0.0-dryrun.42" 0.0.0-dryrun.42 "$case_dir" \
  && stamped_all "a prerelease version" "$case_dir" 0.0.0-dryrun.42; then
  echo "ok   a prerelease version"
fi

for invalid in v1.2.3 1.2 1.2.3+build.1 01.2.3 1.2.3- ""; do
  case_dir="${work}/invalid-${invalid:-empty}"
  fixture "$case_dir"
  if expect "the invalid version '${invalid}'" 1 "is not X.Y.Z or X.Y.Z-<prerelease>" "$invalid" "$case_dir" \
    && unchanged "the invalid version '${invalid}'" "$case_dir"; then
    echo "ok   the invalid version '${invalid}'"
  fi
done

# refuse <case> <text> <cli manifest> <cli lockfile> <app manifest> <app lockfile>:
# the script refuses and changes no file, the three it could stamp included.
refuse() {
  local name="$1" want="$2"
  case_dir="${work}/${name//[^a-zA-Z0-9]/-}"
  fixture "$case_dir" "$3" "$4" "$5" "$6"
  if expect "$name" 1 "$want" 1.2.3 "$case_dir" \
    && holds "$name" "${case_dir}/cli/Cargo.toml" "$3" \
    && holds "$name" "${case_dir}/cli/Cargo.lock" "$4" \
    && holds "$name" "${case_dir}/app/Cargo.toml" "$5" \
    && holds "$name" "${case_dir}/app/Cargo.lock" "$6"; then
    echo "ok   ${name}"
  fi
}

refuse "a CLI Cargo.toml without the placeholder" "holds 0.1.0 as [package] version, not the placeholder 0.0.0-dev" \
  "$(stamped "$cli_manifest" 0.1.0 "$cli_manifest_lines")" "$cli_lockfile" "$app_manifest" "$app_lockfile"
refuse "an app Cargo.toml without the placeholder" "holds 0.1.0 as [workspace.package] version" \
  "$cli_manifest" "$cli_lockfile" "$(stamped "$app_manifest" 0.1.0 "$app_manifest_lines")" "$app_lockfile"
refuse "an app Cargo.toml without a workspace version" "has 0 [workspace.package] version lines, not exactly one" \
  "$cli_manifest" "$cli_lockfile" "${app_manifest/version = \"0.0.0-dev\"
edition/edition}" "$app_lockfile"
refuse "an app Cargo.lock with an app crate at another version" "holds marshal-modes=0.1.0 as path package version" \
  "$cli_manifest" "$cli_lockfile" "$app_manifest" "$(stamped "$app_lockfile" 0.1.0 28)"
refuse "an app Cargo.lock without marshal-app" "has no path package version line for marshal-app" \
  "$cli_manifest" "$cli_lockfile" "$app_manifest" "${app_lockfile/name = \"marshal-app\"/name = \"other-app\"}"
refuse "a CLI Cargo.lock without marshal-cli" "has no path package version line for marshal-cli" \
  "$cli_manifest" "${cli_lockfile/name = \"marshal-cli\"/name = \"marshal-other\"}" "$app_manifest" "$app_lockfile"

crlf() { printf '%s' "$1" | sed 's/$/\r/'; }
case_dir="${work}/crlf"
fixture "$case_dir" "$(crlf "$cli_manifest")"$'\n' "$(crlf "$cli_lockfile")"$'\n' "$(crlf "$app_manifest")"$'\n' "$(crlf "$app_lockfile")"$'\n'
if expect "CRLF files" 0 "to 1.2.3" 1.2.3 "$case_dir" \
  && holds "CRLF files" "${case_dir}/cli/Cargo.toml" "$(crlf "$(stamped "$cli_manifest" 1.2.3 "$cli_manifest_lines")")" \
  && holds "CRLF files" "${case_dir}/app/Cargo.lock" "$(crlf "$(stamped "$app_lockfile" 1.2.3 "$app_lockfile_lines")")"; then
  echo "ok   CRLF files keep their line endings"
fi

# main must keep the placeholder, or every release build refuses.
case_dir="${work}/committed"
mkdir -p "${case_dir}/cli" "${case_dir}/app"
cp "${committed}/cli/Cargo.toml" "${committed}/cli/Cargo.lock" "${case_dir}/cli"
cp "${committed}/app/Cargo.toml" "${committed}/app/Cargo.lock" "${case_dir}/app"
if expect "the committed files" 0 "to 0.0.0-dryrun.1" 0.0.0-dryrun.1 "$case_dir"; then
  stamped_count="$(grep -c '^version = "0.0.0-dryrun.1"' "${case_dir}/app/Cargo.lock")"
  if [[ "$stamped_count" -ne "$(grep -c '^name = "marshal-' "${committed}/app/Cargo.lock")" ]]; then
    fail "the committed app/Cargo.lock: ${stamped_count} versions were stamped, not one for each marshal- crate"
  else
    echo "ok   the committed files hold the placeholder, and every marshal- crate of the app's lockfile is stamped"
  fi
fi

if [[ $failures -ne 0 ]]; then
  echo "${failures} set-release-version case(s) failed." >&2
  exit 1
fi
echo "All set-release-version cases passed."
